export const getCountryCode = (country: string): string => COUNTRY_METADATA[country]?.code || 'xx';
export const getCountryContinent = (country: string): string => COUNTRY_METADATA[country]?.continent || 'Unknown';
export const isCountryInNorthernHemisphere = (country: string): boolean => (COUNTRY_METADATA[country]?.lat ?? 0) >= 0;
export const isCountryInSouthernHemisphere = (country: string): boolean => (COUNTRY_METADATA[country]?.lat ?? 0) < 0;
export const isCountryInEasternHemisphere = (country: string): boolean => (COUNTRY_METADATA[country]?.lng ?? 0) >= 0;
export const isCountryInWesternHemisphere = (country: string): boolean => (COUNTRY_METADATA[country]?.lng ?? 0) < 0;
